CREATE TABLE `chat_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息主键',
  `conversation_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话ID',
  `source_type` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'chat' COMMENT '来源类型：chat普通聊天、group组局、goods商品、system系统',
  `source_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务来源ID',
  `source_title` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '??????',
  `source_desc` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '??????',
  `target_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '?????????',
  `conversation_title` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '会话标题',
  `conversation_avatar` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '会话头像',
  `sender_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送人ID',
  `sender_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'anonymous' COMMENT '发送人昵称',
  `sender_avatar` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发送人头像',
  `content` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容',
  `message_type` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'chat' COMMENT '消息类型：chat聊天消息、system系统消息',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除：0未删除，1已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_conversation_time` (`conversation_id`,`create_time`),
  KEY `idx_sender_id` (`sender_id`)
) ENGINE=InnoDB AUTO_INCREMENT=350 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='聊天消息表';
