DROP TABLE IF EXISTS `lost_found_application`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lost_found_application` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `item_id` bigint NOT NULL COMMENT '物品ID',
  `apply_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'claim领取/return归还',
  `applicant_uid` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人UID',
  `applicant_name` varchar(60) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人姓名',
  `applicant_phone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人电话',
  `applicant_student_id` varchar(40) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人学号',
  `applicant_id_card` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请人身份证号',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT 'pending待同意/approved已同意/rejected已拒绝/completed已完成',
  `is_deleted` tinyint NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_lost_found_app_item` (`item_id`),
  KEY `idx_lost_found_app_user` (`applicant_uid`),
  KEY `idx_lost_found_app_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='失物招领申请';
/*!40101 SET character_set_client = @saved_cs_client */;

