DROP TABLE IF EXISTS `lost_found_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lost_found_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '失物招领ID',
  `type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'lost寻物/found招领',
  `title` varchar(80) COLLATE utf8mb4_general_ci NOT NULL COMMENT '物品标题',
  `description` varchar(500) COLLATE utf8mb4_general_ci NOT NULL COMMENT '描述',
  `location` varchar(120) COLLATE utf8mb4_general_ci NOT NULL COMMENT '地点',
