  `publisher_uid` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发布人UID',
  `publisher_name` varchar(60) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发布人姓名',
  `publisher_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布人手机号',
  `publisher_student_id` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发布人学号',
