--
-- Table structure for table `movie_ticket`
--

DROP TABLE IF EXISTS `movie_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movie_ticket` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `cinema_name` varchar(255) DEFAULT NULL COMMENT '影院名称',
  `movie_name` varchar(255) DEFAULT NULL COMMENT '影片名称',
  `start_date` varchar(50) DEFAULT NULL COMMENT '放映年月日',
  `start_time` varchar(50) DEFAULT NULL COMMENT '开场时间',
  `end_time` varchar(50) DEFAULT NULL COMMENT '结束时间',
  `seat_info` varchar(255) DEFAULT NULL COMMENT '所有座位信息',
  `seat_count` int DEFAULT NULL COMMENT '座位数量(最多4个)',
  `seat_price` varchar(50) DEFAULT NULL COMMENT '单个座位最高价',
  `total_price` varchar(50) DEFAULT NULL COMMENT '订单总价',
  `all_text` text COMMENT 'OCR全部原始识别文本',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='电影票识别记录表';
