--
-- Table structure for table `order_info`
--

DROP TABLE IF EXISTS `order_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单主键',
  `order_no` varchar(32) NOT NULL COMMENT '对外订单编号',
  `user_id` bigint unsigned NOT NULL COMMENT '下单用户id',
  `rider_id` bigint unsigned DEFAULT NULL COMMENT '接单骑手id，未接单为空',
  `parent_type` varchar(20) NOT NULL COMMENT '一级类型：代取/帮买/互助',
  `sub_type` varchar(20) NOT NULL COMMENT '细分类型：快递/奶茶/商超/药品等',
  `start_address_id` bigint DEFAULT NULL COMMENT '取件地址ID（帮买可为空）',
  `end_address_id` bigint NOT NULL COMMENT '送达地址ID',
  `fetch_code` varchar(50) DEFAULT NULL COMMENT '取件码（帮买订单可为空）',
  `remark` varchar(255) DEFAULT '' COMMENT '备注说明',
  `goods_budget` decimal(10,2) DEFAULT NULL COMMENT '帮买物品预算/预支付金额',
  `reward_price` decimal(10,2) DEFAULT '0.00' COMMENT '跑腿赏金/小费',
  `order_price` decimal(10,2) NOT NULL COMMENT '订单费用',
  `expect_time` datetime DEFAULT NULL COMMENT '期望送达时间 格式：yyyy-MM-dd HH:mm',
  `pay_status` tinyint NOT NULL DEFAULT '0' COMMENT '支付状态：0未支付 1已支付',
  `order_status` tinyint NOT NULL DEFAULT '0' COMMENT '订单状态：0待接单 1已接单 2配送中 3已送达 4纠纷中 5已完成 6已撤销',
  `cancel_reason` varchar(255) DEFAULT NULL COMMENT '用户取消订单原因',
  `cancel_apply_count` int NOT NULL DEFAULT '0' COMMENT '客户申请取消次数',
  `lifecycle_log` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '订单生命流程日志',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除 0-未删除 1-已删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '下单时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `pre_order_status` tinyint DEFAULT NULL COMMENT '订单状态临时存储',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_order_no` (`order_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_rider_id` (`rider_id`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单主表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `order_info`
--

LOCK TABLES `order_info` WRITE;
/*!40000 ALTER TABLE `order_info` DISABLE KEYS */;
