CREATE TABLE `organization_activity` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '??ID',
  `title` varchar(80) COLLATE utf8mb4_general_ci NOT NULL COMMENT '????',
  `category` varchar(40) COLLATE utf8mb4_general_ci NOT NULL COMMENT '???',
  `tag_id` int DEFAULT NULL COMMENT '??ID',
  `tag_name` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '????',
  `activity_time` varchar(40) COLLATE utf8mb4_general_ci NOT NULL COMMENT '????????',
  `address` varchar(120) COLLATE utf8mb4_general_ci NOT NULL COMMENT '????',
  `max_people` int NOT NULL DEFAULT '2' COMMENT '????',
  `join_num` int NOT NULL DEFAULT '0' COMMENT '?????',
  `gender_limit` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '??' COMMENT '????',
  `fee_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '??' COMMENT '????',
  `deposit_required` tinyint NOT NULL DEFAULT '0' COMMENT '??????',
  `deposit_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '????',
  `host_desc` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '?????',
  `poster_img` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '/static/organization/feature-card.jpg' COMMENT '???',
  `brand_name` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '????' COMMENT '?????',
  `brand_avatar` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '/static/default-avatar.png' COMMENT '?????',
  `group_count` int NOT NULL DEFAULT '1' COMMENT '???????',
  `qrcode_url` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '/static/11/1.png' COMMENT '?????',
  `creator_user_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'system' COMMENT '?????ID',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '?? active/review/closed',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '????',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '????',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '????',
  PRIMARY KEY (`id`),
  KEY `idx_org_activity_status` (`status`,`is_deleted`),
  KEY `idx_org_activity_creator` (`creator_user_id`),
  KEY `idx_org_activity_tag` (`tag_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='??????';
