--
-- Table structure for table `tb_rider_order`
--

DROP TABLE IF EXISTS `tb_rider_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_rider_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rider_order_no` varchar(32) NOT NULL COMMENT '骑手专属订单编号',
  `order_no` varchar(32) NOT NULL COMMENT '关联主订单号',
  `rider_user_id` varchar(30) NOT NULL COMMENT '接单骑手ID',
  `accept_time` datetime DEFAULT NULL COMMENT '骑手接单时间',
  `pick_time` datetime DEFAULT NULL COMMENT '实际取件时间',
  `deliver_time` datetime DEFAULT NULL COMMENT '送达确认时间',
  `finish_time` datetime DEFAULT NULL COMMENT '订单最终完结时间',
  `rider_status` tinyint NOT NULL DEFAULT '0' COMMENT '订单状态：0待接单 1已接单 2配送中 3已送达 4纠纷中 5已完成 6已撤销',
  `service_fee` decimal(10,2) DEFAULT '0.00' COMMENT '骑手实际到手佣金',
  `cancel_reason` varchar(255) DEFAULT '' COMMENT '弃单/取消原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常 1删除',
  `pre_delivery_status` tinyint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rider_order_no` (`rider_order_no`),
  KEY `idx_order_id` (`order_no`),
  KEY `idx_rider_id` (`rider_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='骑手订单关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_rider_order`
--

LOCK TABLES `tb_rider_order` WRITE;
/*!40000 ALTER TABLE `tb_rider_order` DISABLE KEYS */;
