--
-- Table structure for table `user`
--

DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `uid` varchar(32) NOT NULL COMMENT '全局唯一用户ID，用于App/小程序统一标识',
  `openid` varchar(50) DEFAULT NULL COMMENT '微信openid，小程序端唯一标识',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号，登录账号',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱账号',
  `password` varchar(100) DEFAULT NULL COMMENT 'App端密码，小程序端可为空',
  `username` varchar(50) DEFAULT NULL COMMENT '用户昵称',
  `avatar` varchar(255) DEFAULT NULL COMMENT '用户头像URL',
  `role` tinyint DEFAULT '0' COMMENT '角色：0普通用户 1管理员',
  `real_name` varchar(20) DEFAULT NULL COMMENT '真实姓名',
  `gender` tinyint unsigned DEFAULT '0' COMMENT '性别：0未知 1男 2女',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号码',
  `birthday` date DEFAULT NULL COMMENT '生日',
  `qq` varchar(20) DEFAULT NULL COMMENT 'QQ号',
  `wechat` varchar(50) DEFAULT NULL COMMENT '微信号',
  `alipay_account` varchar(100) DEFAULT NULL COMMENT '支付宝账号',
  `student_id` varchar(20) DEFAULT NULL COMMENT '学号',
  `college` varchar(50) DEFAULT NULL COMMENT '学院',
  `major` varchar(50) DEFAULT NULL COMMENT '专业',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级',
  `dormitory` varchar(50) DEFAULT NULL COMMENT '寝室信息',
  `hobby` varchar(255) DEFAULT NULL COMMENT '爱好',
  `status` tinyint DEFAULT '1' COMMENT '状态：1正常 0禁用',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除 0-未删除 1-已删除',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) DEFAULT NULL COMMENT '最后登录IP',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uid` (`uid`),
  UNIQUE KEY `uk_uid` (`uid`),
  UNIQUE KEY `phone` (`phone`),
  UNIQUE KEY `uk_phone` (`phone`),
  UNIQUE KEY `uk_openid` (`openid`),
  UNIQUE KEY `idx_user_email` (`email`),
  UNIQUE KEY `idx_user_alipay` (`alipay_account`),
  UNIQUE KEY `idx_user_wechat` (`wechat`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='多端兼容用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

