--
-- Table structure for table `user_address`
--

DROP TABLE IF EXISTS `user_address`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_address` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `address_no` varchar(40) DEFAULT NULL COMMENT '地址对外编号',
  `user_id` bigint unsigned NOT NULL COMMENT '关联用户ID',
  `receiver_name` varchar(50) NOT NULL COMMENT '收货人姓名',
  `receiver_phone` char(11) NOT NULL COMMENT '收货人手机号',
  `address_type` tinyint NOT NULL COMMENT '地址类型：1校园 2校外',
  `address` varchar(255) NOT NULL COMMENT '完整地址（校区+楼栋+楼层+门牌号）',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认地址：1是 0否',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除 0-未删除 1-已删除',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_user_address_no` (`address_no`),
  KEY `idx_user_id` (`user_id`)
