--
-- Table structure for table `wall_comment`
--

DROP TABLE IF EXISTS `wall_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wall_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `post_id` bigint NOT NULL COMMENT '关联帖子ID',
  `user_id` bigint NOT NULL COMMENT '评论用户ID，内部关联用，不对外暴露',
  `user_uid` varchar(32) NOT NULL COMMENT '用户对外脱敏UID，前端交互专用',
  `is_anonymous` tinyint DEFAULT '0' COMMENT '0实名 1匿名评论',
  `content` varchar(500) NOT NULL COMMENT '评论内容',
  `media_urls` varchar(500) DEFAULT NULL COMMENT '媒体资源URL（图片链接）',
  `like_count` int DEFAULT '0' COMMENT '评论点赞数',
  `parent_id` bigint DEFAULT '0' COMMENT '父评论ID，0=顶级评论',
  `reply_comment_id` bigint DEFAULT '0' COMMENT '回复指定评论ID',
  `reply_user_id` bigint DEFAULT '0' COMMENT '被回复用户ID，内部关联用',
  `reply_user_uid` varchar(32) DEFAULT '' COMMENT '被回复用户脱敏UID，前端交互专用',
  `is_deleted` tinyint DEFAULT '0' COMMENT '软删除 0正常 1删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_post_id` (`post_id`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='表白墙评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

