CREATE TABLE `wall_post` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '帖子ID',
  `post_no` varchar(32) NOT NULL COMMENT '公开帖子编号',
  `user_id` bigint NOT NULL COMMENT '发布用户ID',
  `category_id` bigint NOT NULL COMMENT '一级分类ID',
  `sub_category_id` bigint NOT NULL DEFAULT '0' COMMENT '二级子分类ID',
  `nickname` varchar(30) DEFAULT '' COMMENT '昵称',
  `avatar` varchar(255) DEFAULT '' COMMENT '头像地址',
  `is_anonymous` tinyint DEFAULT '0' COMMENT '0实名 1匿名',
  `content` varchar(800) DEFAULT NULL COMMENT '帖子文字内容',
  `view_count` int DEFAULT '0' COMMENT '浏览量',
  `like_count` int DEFAULT '0' COMMENT '帖子点赞数',
  `collect_count` int DEFAULT '0' COMMENT '收藏数',
  `comment_count` int DEFAULT '0' COMMENT '评论总数',
  `status` tinyint DEFAULT '0' COMMENT '0待审核 1审核通过 2驳回',
  `is_top` tinyint DEFAULT '0' COMMENT '是否置顶 0否 1是',
  `top_expire_time` datetime DEFAULT NULL COMMENT '置顶过期时间',
  `publish_time` datetime DEFAULT NULL COMMENT '定时发布时间',
  `is_timing` tinyint DEFAULT '0' COMMENT '0立即发布 1定时发布',
  `is_deleted` tinyint DEFAULT '0' COMMENT '软删除 0正常 1删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wall_post_post_no` (`post_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_status_top` (`status`,`is_top`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='表白墙帖子';
/*!40101 SET character_set_client = @saved_cs_client */;

