--
-- Table structure for table `wall_report`
--

DROP TABLE IF EXISTS `wall_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wall_report` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '举报人ID',
  `post_id` bigint DEFAULT '0' COMMENT '举报帖子ID',
  `comment_id` bigint DEFAULT '0' COMMENT '举报评论ID',
  `report_type` tinyint NOT NULL COMMENT '举报类型',
  `reason` varchar(500) DEFAULT '' COMMENT '举报原因',
  `status` tinyint DEFAULT '0' COMMENT '0待处理 1已处理 2驳回',
